//! Module cache.

use std::collections::BTreeMap;

pub fn count_0(input: &str) -> BTreeMap<String, usize> {
    let mut counts = BTreeMap::new();
    for word in input.split_whitespace() {
        *counts.entry(word.to_string()).or_insert(0) += 1;
    }
    counts
}

